const img_base   = perfil.img_prompt_base   || '';
const img_estilo = perfil.img_prompt_estilo || 'realistic photo, natural lighting, high quality';
const img_neg    = perfil.img_prompt_negativo || 'cartoon, anime, ugly, deformed';

const user_prompt = `Eres experto en prompts para generacion de imagenes con IA.\n\nAVATAR:\n${img_base}\nEstilo visual: ${img_estilo}\nEvitar: ${img_neg}\n\nINSTRUCCIONES ACTIVAS DE IMAGEN:\n${instrImgTexto}\n\nPOST GENERADO:\n'${anterior.texto_generado}'\n\nGenera un prompt en INGLES de maximo 80 palabras que describa una foto del avatar acorde al post. Incluye siempre la descripcion fisica del avatar. Solo el prompt, sin explicaciones.`;

return [{ json: { ...anterior, user_prompt_imagen: user_prompt } }];

const respGroq = $input.item.json;
const anterior = $('Construir prompt de imagen').item.json;

const promptImagen = respGroq.choices?.[0]?.message?.content?.trim() || (anterior.perfil?.img_prompt_base + ', ' + anterior.perfil?.img_prompt_estilo) || 'realistic photo, influencer, natural lighting, high quality';

return [{ json: {
