const base = $('Detectar comando').item.json;
let comando   = base.comando;
let argumento = base.argumento;
const is_callback = base.is_callback || false;
const msg = base.mensaje_raw || '';

// Leer estado pendiente del config
const estadoItems = $input.all();
const estadoRow = estadoItems.find(i => i.json.clave === 'estado_pendiente');
const estadoValor = estadoRow?.json?.valor || '';

// Comandos que requieren argumento obligatorio
const requierenArg = {
  'instruccion':     { pregunta: '💡 Escribe la instrucción que quieres enseñarle al avatar:', botones: null },
  'instruccion_off': { pregunta: '🔕 Selecciona la instrucción a desactivar:', botones: 'instrucciones' },
  'avatar':          { pregunta: '🎭 ¿Qué avatar quieres activar?', botones: 'avatares' },
  'publicar':        { pregunta: '🎨 ¿Para qué marca generamos el banner?', botones: 'marcas' },
  'post':            { pregunta: '📱 Escribe el tema del post (ej: outfit de verano):', botones: null }
};

// Post necesita red + tema. Si solo trae la red (1 palabra), pedir el tema.
function postFaltaTema(cmd, arg) {
  if (cmd !== 'post') return false;
  const partes = (arg || '').trim().split(/\s+/).filter(Boolean);
  return partes.length < 2; // menos de 2 palabras = falta el tema
}

// ── CASO 1: Hay estado pendiente y el usuario mandó texto libre (no comando, no callback) ──
const esComandoNuevo = msg.startsWith('/') || is_callback;
if (estadoValor && !esComandoNuevo) {
  const [cmdPendiente, extra] = estadoValor.split('|');
  comando = cmdPendiente;
  // Combinar extra (si existe) con el texto nuevo
  argumento = extra ? (extra + ' ' + msg).trim() : msg.trim();

  return [{ json: {
    ...base,
    comando,
    argumento,
    accion: 'ejecutar',
    limpiar_estado: true
  } }];
}

// ── CASO 2: Comando nuevo que requiere argumento pero llegó vacío ──
if (requierenArg[comando] && ((!argumento || argumento.trim() === '') || postFaltaTema(comando, argumento))) {
  // Caso especial post: si el callback trae "instagram libre" o similar, igual pedir tema
  const cfg = requierenArg[comando];

  // post desde botón trae la red ya, pero necesita tema → guardar "post|instagram"
  let extraGuardar = '';
  if (comando === 'post' && argumento && argumento.trim() !== '') {
    extraGuardar = argumento.trim().split(' ')[0]; // la red social
  }

  return [{ json: {
    ...base,
    comando,
    accion: 'pedir',
    pedir_pregunta: cfg.pregunta,
    pedir_botones: cfg.botones || '',
    estado_guardar: comando + '|' + extraGuardar
  } }];
}

// ── CASO 3: Comando normal con argumento, o comando sin requisito ──
return [{ json: {
  ...base,
  comando,
  argumento,
  accion: 'ejecutar',
  limpiar_estado: estadoValor ? true : false
} }];

