const base = $('Resolver intencion').item.json;

// Avatar activo desde config
const configItems = $('Leer avatar activo (off)').all();
const avatar_activo = configItems.find(i => i.json.clave === 'avatar_activo')?.json?.valor || 'sofia_01';

// Instrucciones activas de ESE avatar
