const items = $('Apify TikTok trends BO').all().map(i => i.json);

function num(n) {
  n = Number(n) || 0;
  if (n >= 1e9) return (n/1e9).toFixed(1)+'B';
  if (n >= 1e6) return (n/1e6).toFixed(1)+'M';
  if (n >= 1e3) return (n/1e3).toFixed(1)+'K';
  return String(n);
}
function limpiar(t){ return String(t||'').replace(/[_*\[\]()~`>#+=|{}]/g,'').trim(); }

// El actor devuelve items con campo 'type' (hashtag/sound/video) según el screenshot
const hashtags = items.filter(x => x.type === 'hashtag');
const sonidos  = items.filter(x => x.type === 'sound' || x.type === 'song' || x.type === 'music');
const videos   = items.filter(x => x.type === 'video');

const arrow = { rising:'📈', falling:'📉', stable:'➡️' };

